private string EncodePassword (string pass, MembershipPasswordFormat format)
        {
            switch (format) {
                case MembershipPasswordFormat.Clear:
                    return pass;
                case MembershipPasswordFormat.Encrypted:
                    throw new NotSupportedException ("Encryption not supported.");
                case MembershipPasswordFormat.Hashed:
                    return EncodePassword (pass, "SHA1", true);
            }
            throw new ArgumentException ("Unrecognized password format.");
        }

private string EncodePassword (string pass, string alg, bool useHashing)
        {
            byte[] saltBytes = GetSalt ();
            byte[] plainTextBytes = Encoding.UTF8.GetBytes (pass);
            byte[] allBytes = new byte[saltBytes.Length + plainTextBytes.Length];
            Buffer.BlockCopy (saltBytes, 0, allBytes, 0, saltBytes.Length);
            Buffer.BlockCopy (plainTextBytes, 0, allBytes, saltBytes.Length, plainTextBytes.Length);
            if (useHashing) {
                HashAlgorithm hash = HashAlgorithm.Create (alg);
                byte[] hashBytes = hash.ComputeHash (allBytes);
                return Convert.ToBase64String (hashBytes);
            }
            return Convert.ToBase64String (allBytes);
        }

