private static string EncodePassword (string pass, int passwordFormat, string salt)
{
	byte[] data = Encoding.UTF8.GetBytes (pass + salt);
	switch (passwordFormat)
	{
		case 0: // Hashed
			return Convert.ToBase64String (new MD5CryptoServiceProvider ().ComputeHash (data));
		case 1: // Encrypted
			return Convert.ToBase64String (EncryptPassword (data));
		case 2: // Clear
			return pass;
		default:
			throw new ArgumentException ("Unrecognized password format.");
	}
}

